class MaxBalancedPartition {
  public int solve(String s) {
    int height = 0;
    int res = 0;
    for (char c : s.toCharArray()) {
      if (c == '(') {
        height++;
      } else {
        height--;
        if (height == 0) {
          res++;
        }
      }
    }
    return res;
  }
}

